+    for (const artifact of ['spec.json', 'events.jsonl', 'result.json', 'terminal.json']) {
+      const artifactPath = join(sealedRunDir, artifact);
+      const original = readFileSync(artifactPath, 'utf8');
+      writeFileSync(artifactPath, `${original} `);
+      assert.throws(
