   700	/** A terminal writer may legitimately outlive staleMs; PID reuse is fenced by process start time. */
   701	export function classifyManagedHostRunTerminalLock(snapshot: ExistingMkdirLockSnapshot): ExistingMkdirLockState {
   702	  const holder = snapshot.holder;
   703	  if (!holder || holder.hostname !== hostname()) return 'unknown';
   704	  if (!Number.isInteger(holder.pid) || holder.pid <= 0) return 'unknown';
   705	  try {
   706	    process.kill(holder.pid, 0);
   707	  } catch (error) {
   708	    const code = (error as NodeJS.ErrnoException).code;
   709	    if (code === 'ESRCH') return 'stale';
   710	    if (code !== 'EPERM') return 'unknown';
   711	  }
   712	  const observedStart = processStartTimeMsForPid(holder.pid);
   713	  if (!sameProcessStart(holder.processStartTimeMs, observedStart)) return 'stale';
   714	  // A live PID with an unobservable start time is conservatively active. The
   715	  // bounded acquisition deadline reports contention instead of stealing it.
   716	  return 'active';
   717	}
