   724	  result: HostRunResult | null,
   725	  now: number,
   726	): ManagedHostRunTerminal {
   727	  return withMkdirLock(paths.terminalLock, () => {
   728	    const existing = readTerminal(paths);
   729	    if (existing) return existing;
   730	
   731	    if (result) atomicWrite(paths.result, result);
   732	    const specText = readFileSync(paths.spec, 'utf8');
   733	    const snapshot = readJson<ManagedHostRunSnapshot>(paths.snapshot);
   734	    const terminal: ManagedHostRunTerminal = {
   735	      schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
   736	      runId: snapshot.runId,
   737	      state,
   738	      reason,
   739	      terminalAt: new Date(now).toISOString(),
   740	      generation: snapshot.generation + 1,
   741	      replacementSafe,
   742	      resultDigest: digestFile(paths.result),
   743	      eventJournalDigest: digestFile(paths.events) ?? sha256(''),
   744	      specDigest: sha256(specText),
   745	      evidenceProposalDigest: digestFile(paths.evidenceProposal),
   746	      processCleanup: result?.processCleanup ?? (
