   781	/**
   782	 * Production launcher. Ordinary one-shot input remains in the run directory;
   783	 * a formal-review signing key crosses only an inherited pipe, never argv, env,
   784	 * prompt text, or a durable plaintext artifact. stdout/stderr are append-only
   785	 * worker diagnostics, not the provider live-output protocol.
   786	 */
   787	export const defaultManagedHostRunWorkerLauncher: ManagedHostRunWorkerLauncher = request => {
   788	  assertManagedHostRunPlatformSupported(process.platform);
   789	  const paths = pathsFor(request.root, request.runId);
   790	  const entrypoint = process.argv[1];
   791	  if (!entrypoint) throw new Error('managed host run: cannot resolve the current lattice CLI entrypoint');
   792	  const logFd = openSync(paths.workerLog, 'a', 0o600);
   793	  try {
   794	    const hasInvocationKey = typeof request.proposalInvocationPrivateKey === 'string';
   795	    const child = spawn(
   796	      process.execPath,
   797	      [entrypoint, '--root', request.root, 'host_run_worker', JSON.stringify({ runId: request.runId })],
   798	      {
   799	        cwd: request.root,
   800	        env: hasInvocationKey
   801	          ? { ...process.env, LATTICE_MANAGED_HOST_WORKER_CAPABILITY_FD: '3' }
   802	          : process.env,
   803	        detached: true,
   804	        stdio: hasInvocationKey ? ['ignore', logFd, logFd, 'pipe'] : ['ignore', logFd, logFd],
   805	      },
   806	    );
   807	    if (!child.pid) throw new Error('managed host run: detached worker did not expose a pid');
   808	    if (hasInvocationKey) {
   809	      const descriptor = child.stdio[3];
   810	      if (!descriptor || !('end' in descriptor)) throw new Error('managed host run: worker capability descriptor unavailable');
   811	      descriptor.end(request.proposalInvocationPrivateKey);
   812	    }
   813	    child.unref();
   814	    return { pid: child.pid };
   815	  } finally {
   816	    closeSync(logFd);
   817	  }
   818	};
